    apply (lap_of_run tm Cc true true cho_1RB1LA_1LC1RD_1LA0LC_0RD1LC B0_1RB1LA_1LC1RD_1LA0LC_0RD1LC B1_1RB1LA_1LC1RD_1LA0LC_0RD1LC 4 16 p j' [] []).
