(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LA_1LC1RD_1LA0LC_0RD1LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LA_1LC1RD_1LA0LC_0RD1LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1LA_1LC1RD_1LA0LC_0RD1LC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LA_1LC1RD_1LA0LC_0RD1LC p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LA_1LC1RD_1LA0LC_0RD1LC : forall t, ~ In t pins_1RB1LA_1LC1RD_1LA0LC_0RD1LC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1LA_1LC1RD_1LA0LC_0RD1LC.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB1LA_1LC1RD_1LA0LC_0RD1LC
      with (l := [SWin 4]).
    vm_compute; reflexivity.
  - (* A1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* B0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1LA_1LC1RD_1LA0LC_0RD1LC
      with (l := [SWin 5]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1LA_1LC1RD_1LA0LC_0RD1LC
      with (l := [SWin 3]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1LA_1LC1RD_1LA0LC_0RD1LC
      with (l := [SWin 7]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1LA_1LC1RD_1LA0LC_0RD1LC
      with (l := []).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB1LA_1LC1RD_1LA0LC_0RD1LC
      with (l := [SWin 2]).
    vm_compute; reflexivity.
Qed.

Theorem qhtr_1RB1LA_1LC1RD_1LA0LC_0RD1LC : NonHalt tm_1RB1LA_1LC1RD_1LA0LC_0RD1LC /\ QHBoundTr 32779478 tm_1RB1LA_1LC1RD_1LA0LC_0RD1LC /\ QuasiHaltsTr tm_1RB1LA_1LC1RD_1LA0LC_0RD1LC.
Proof.
  apply (lap_qh_stage tm_1RB1LA_1LC1RD_1LA0LC_0RD1LC pins_1RB1LA_1LC1RD_1LA0LC_0RD1LC Cc 1 19 32779478).
  - exact bootq_1RB1LA_1LC1RD_1LA0LC_0RD1LC.
  - intros p _. apply lap_1RB1LA_1LC1RD_1LA0LC_0RD1LC.
  - intros t Ht p _. apply fire_1RB1LA_1LC1RD_1LA0LC_0RD1LC. exact Ht.
  - exact wit_1RB1LA_1LC1RD_1LA0LC_0RD1LC.
  - apply qcleb_QC_19. reflexivity.
