    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_1LC1RD_1LA1RD_0LA0RB [SWin 3; SWinR 2] (StA, S1) ltac:(vm_compute; reflexivity)
