    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_1LC1RD_1LA1RD_0LA0RB [SWin 3; SWinR 9; SCycL 2 0; SWin 6; SCycR 2; SWin 5] (StC, S0) ltac:(vm_compute; reflexivity)
