    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_1LC1RD_1RA0RB_0LA0RB [SCycL 2 0; SWin 5] (StD, S1) ltac:(vm_compute; reflexivity)
