Theorem qhtr_1RB1LA_1LC1RD_1RA0RB_0LA0RB : NonHalt tm_1RB1LA_1LC1RD_1RA0RB_0LA0RB /\ QHBoundTr 32779478 tm_1RB1LA_1LC1RD_1RA0RB_0LA0RB /\ QuasiHaltsTr tm_1RB1LA_1LC1RD_1RA0RB_0LA0RB.
