(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1LA_1LC1RD_1RA0RD_0LA0RB : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A0_1RB1LA_1LC1RD_1RA0RD_0LA0RB.
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p j q0 E) as (H1 & _).
  unfold Cc_1RB1LA_1LC1RD_1RA0RD_0LA0RB, cden, A0_1RB1LA_1LC1RD_1RA0RD_0LA0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

(** The lap ends on [S1;S0] where the anchor has [S1] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_1RB1LA_1LC1RD_1RA0RD_0LA0RB : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A1_1RB1LA_1LC1RD_1RA0RD_0LA0RB) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p j q0 E) as (_ & H2).
  unfold Cc_1RB1LA_1LC1RD_1RA0RD_0LA0RB, cden, A1_1RB1LA_1LC1RD_1RA0RD_0LA0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S1;S0]) with (([S1]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1LA_1LC1RD_1RA0RD_0LA0RB : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E.
  exists (4 * j + 12), (cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A1_1RB1LA_1LC1RD_1RA0RD_0LA0RB).
  split; [lia|]. split; [| exact (gei_1RB1LA_1LC1RD_1RA0RD_0LA0RB p j q0 E)].
  rewrite (gsi_1RB1LA_1LC1RD_1RA0RD_0LA0RB p j q0 E).
  exact (srun_sound tm false true chi_1RB1LA_1LC1RD_1RA0RD_0LA0RB A0_1RB1LA_1LC1RD_1RA0RD_0LA0RB A1_1RB1LA_1LC1RD_1RA0RD_0LA0RB 4 12
           run_int_1RB1LA_1LC1RD_1RA0RD_0LA0RB (Ap_Alph_10_11_11 q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_1RB1LA_1LC1RD_1RA0RD_0LA0RB : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1LA_1LC1RD_1RA0RD_0LA0RB.
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (H1 & _).
  unfold Cc_1RB1LA_1LC1RD_1RA0RD_0LA0RB, cden, B0_1RB1LA_1LC1RD_1RA0RD_0LA0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB1LA_1LC1RD_1RA0RD_0LA0RB : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1LA_1LC1RD_1RA0RD_0LA0RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LA_1LC1RD_1RA0RD_0LA0RB) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1LA_1LC1RD_1RA0RD_0LA0RB
             = (StA, (rep [S1;S0] (S j) ++ [S1;S1], S1, [S1]))).
  { unfold cden, B1_1RB1LA_1LC1RD_1RA0RD_0LA0RB, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StA, ((rep [S1;S0] (S j) ++ [S1;S1]) ++ [S0], S1, [S1]))).
  { unfold Cc_1RB1LA_1LC1RD_1RA0RD_0LA0RB. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB1LA_1LC1RD_1RA0RD_0LA0RB. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_1RB1LA_1LC1RD_1RA0RD_0LA0RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LA_1LC1RD_1RA0RD_0LA0RB p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LA_1LC1RD_1RA0RD_0LA0RB B0_1RB1LA_1LC1RD_1RA0RD_0LA0RB B1_1RB1LA_1LC1RD_1RA0RD_0LA0RB 4 11 p j' [] []).
    + exact run_ovf_1RB1LA_1LC1RD_1RA0RD_0LA0RB.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LA_1LC1RD_1RA0RD_0LA0RB p j' E).
    + exact (geo_1RB1LA_1LC1RD_1RA0RD_0LA0RB p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB1LA_1LC1RD_1RA0RD_0LA0RB : stepn tm_1RB1LA_1LC1RD_1RA0RD_0LA0RB 14 InitES = Some (lift (Cc 1)).
Proof.
  assert (H : match csteps tm_1RB1LA_1LC1RD_1RA0RD_0LA0RB 14 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm_1RB1LA_1LC1RD_1RA0RD_0LA0RB 14 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB1LA_1LC1RD_1RA0RD_0LA0RB : existsb (fun tg => cfires tm_1RB1LA_1LC1RD_1RA0RD_0LA0RB c0 14 tg) pins_1RB1LA_1LC1RD_1RA0RD_0LA0RB = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LA_1LC1RD_1RA0RD_0LA0RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LA_1LC1RD_1RA0RD_0LA0RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1LA_1LC1RD_1RA0RD_0LA0RB p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LA_1LC1RD_1RA0RD_0LA0RB p j E)].
Qed.


(** An instruction that fires ONLY inside the interior lap: [vis_via_ovf] runs to an
    OVERFLOW anchor, so it cannot see one.  This is the interior witness, and
    [LapCertGlueLift.fire_via_int_lift] carries it to every anchor. *)
Lemma firei_1RB1LA_1LC1RD_1RA0RD_0LA0RB : forall (l : list lstep) (t : Instr),
  srun_instr tm false true l A0_1RB1LA_1LC1RD_1RA0RD_0LA0RB = Some t ->
  forall p j q0, cview p = (j, Some q0) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j q0 E.
  apply (fire_of_run_instr tm Cc false true l A0_1RB1LA_1LC1RD_1RA0RD_0LA0RB p j (Ap_Alph_10_11_11 q0 ++ [S0]) []);
    [exact Hst | discriminate | reflexivity | exact (gsi_1RB1LA_1LC1RD_1RA0RD_0LA0RB p j q0 E)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LA_1LC1RD_1RA0RD_0LA0RB : forall t, ~ In t pins_1RB1LA_1LC1RD_1RA0RD_0LA0RB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB1LA_1LC1RD_1RA0RD_0LA0RB.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_1LC1RD_1RA0RD_0LA0RB [SCycL 2 0; SWin 3] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_1LC1RD_1RA0RD_0LA0RB [] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_1LC1RD_1RA0RD_0LA0RB [SCycL 2 0; SWin 6; SCycR 2; SWin 1; SWinR 1] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_1LC1RD_1RA0RD_0LA0RB [SCycL 2 0; SWin 4] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_1LC1RD_1RA0RD_0LA0RB [SCycL 2 0; SWin 6; SCycR 2; SWin 1; SWinR 2] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* D0: fires only in the interior lap *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_int_lift tm Cc lap_1RB1LA_1LC1RD_1RA0RD_0LA0RB (StD, S0)).
    intros p1 j1 r1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (firei_1RB1LA_1LC1RD_1RA0RD_0LA0RB [SCycL 2 0; SWin 4; SCycR 2; SWin 1; SWinR 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 r1 E1).
  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_1LC1RD_1RA0RD_0LA0RB [SCycL 2 0; SWin 5] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem qhtr_1RB1LA_1LC1RD_1RA0RD_0LA0RB : NonHalt tm_1RB1LA_1LC1RD_1RA0RD_0LA0RB /\ QHBoundTr 32779478 tm_1RB1LA_1LC1RD_1RA0RD_0LA0RB /\ QuasiHaltsTr tm_1RB1LA_1LC1RD_1RA0RD_0LA0RB.
Proof.
  apply (lap_qh_stage tm_1RB1LA_1LC1RD_1RA0RD_0LA0RB pins_1RB1LA_1LC1RD_1RA0RD_0LA0RB Cc 1 14 32779478).
  - exact bootq_1RB1LA_1LC1RD_1RA0RD_0LA0RB.
  - intros p _. apply lap_1RB1LA_1LC1RD_1RA0RD_0LA0RB.
  - intros t Ht p _. apply fire_1RB1LA_1LC1RD_1RA0RD_0LA0RB. exact Ht.
  - exact wit_1RB1LA_1LC1RD_1RA0RD_0LA0RB.
  - apply qcleb_QC_19. reflexivity.
Qed.

End B_QC_19_023.

