  apply (fire_of_run_instr tm Cc true true l B0_1RB1LA_1LC1RD_1RA1RD_0LA0RB p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LA_1LC1RD_1RA1RD_0LA0RB p j E)].
