    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LA_1LC1RD_1RB1RA_0LA0RB [SCycL 2 0; SWin 4] (StB, S1) ltac:(vm_compute; reflexivity)
